{"implementation":"def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    core = payload['core_distance']
    distances = payload['distances']
    mr = {}
    for u, v, d in distances:
        a, b = min(u, v), max(u, v)
        mr[(a, b)] = max(core[u], core[v], d)
    edges = [(w, a, b) for (a, b), w in mr.items()]
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst = []
    for w, a, b in edges:
        if union(a, b):
            mst.append([a, b, w])
        if len(mst) == len(nodes) - 1:
            break
    return {'mst_edges': mst}"}
